// Client helper to register for push notifications on Capacitor (Android)
// Usage: call registerFCM(supabase, userId) after user is authenticated

import { PushNotifications } from '@capacitor/push-notifications';
import { Capacitor } from '@capacitor/core';
import { supabase } from '../supabase';
import { getSystemInfo } from './getSystemInfo';

let fcmRegistered = false;

export async function registerFCM(userId) {
  if (fcmRegistered) {
    console.log('FCM already registered, skipping duplicate registration');
    return null;
  }

  if (!Capacitor.isNativePlatform()) {
    console.warn('FCM registration skipped: not running on native platform.');
    return null;
  }

  if (Capacitor.getPlatform() !== 'android') {
    console.warn('FCM registration skipped: not running on Android.');
    return null;
  }

  try {
    const currentPerm = await PushNotifications.checkPermissions();
    const perm = currentPerm.receive === 'granted'
      ? currentPerm
      : await PushNotifications.requestPermissions();

    if (perm.receive !== 'granted') {
      console.warn('Push permission not granted');
      return null;
    }

    try {
      await PushNotifications.register();
    } catch (err) {
      console.error('Firebase push registration failed:', err);
      if (err?.message?.includes('Default FirebaseApp is not initialized')) {
        console.warn('Android Firebase is not configured. Add android/app/google-services.json and rebuild the app.');
      }
      return null;
    }

    fcmRegistered = true;

    return new Promise((resolve, reject) => {
      const registrationHandler = PushNotifications.addListener('registration', async (token) => {
        try {
          console.log('[FCM] Token received:', token.value);
          const systemInfo = await getSystemInfo();
          console.log('[FCM] System info:', systemInfo);
          
          const result = await supabase.rpc('upsert_device_token', {
            _user_id: userId,
            _token: token.value,
            _platform: 'android',
            _metadata: systemInfo
          });
          
          console.log('[FCM] upsert_device_token result:', result);
          
          try {
            localStorage.setItem('device_token', token.value);
            console.log('[FCM] ✅ Device token stored in localStorage');
          } catch (storageErr) {
            console.warn('[FCM] Could not persist device token to localStorage:', storageErr);
          }
          resolve(token.value);
        } catch (err) {
          console.error('[FCM] Failed to register token with Supabase:', err);
          reject(err);
        } finally {
          registrationHandler.remove();
        }
      });

      PushNotifications.addListener('registrationError', (err) => {
        console.error('[FCM] Registration error:', err);
        registrationHandler.remove();
        reject(err);
      });

      // Listen for push notifications received while app is in foreground
      PushNotifications.addListener('pushNotificationReceived', (notification) => {
        console.log('[FCM] Push notification received:', notification);

        if (typeof document !== 'undefined' && document.visibilityState !== 'visible') {
          console.log('[FCM] App is not visible, skipping foreground notification handling');
          return;
        }

        // Extract notification details
        const title = notification.title || 'Notification';
        const body = notification.body || 'New notification';
        const badge = notification.data?.badge || notification.badge;
        const notificationData = {
          title,
          body,
          badge: badge ? Number(badge) : undefined,
          data: notification.data,
          actionTypeId: 'notification_actions',
        };

        if (window.showFCMNotification) {
          window.showFCMNotification(notificationData);
        }
      });

      // Handle tap on notification (when app is in foreground or background)
      PushNotifications.addListener('pushNotificationActionPerformed', (notification) => {
        console.log('[FCM] Push notification action performed:', notification);
        
        // Navigate to notifications page if needed
        const action = notification.notification?.actionId;
        const deep = notification.notification?.click_action;
        if (action || deep) {
          if (window.onNotificationTap) {
            window.onNotificationTap({ action, deep });
          }
        }
      });
    });
  } catch (err) {
    console.error('registerFCM error', err);
    return null;
  }
}

export default registerFCM;
